// 1. RECUPERA OS ITENS (Devem vir diretamente do Planilha Rush1 ou filtro de tabela)
const items = $input.all();

// 2. RECUPERA O CONTEXTO DO SITE (Se disponível)
let contextoSite = "Conteúdo do site não disponível.";
try {
    contextoSite = $('HTML to Markdown').first().json.conteudo_site || "";
} catch (e) {}

// 3. MAPEAMENTO MANUAL EXATO (Baseado na imagem Planilha Rush1)
const listaEstruturada = items.map(item => {
    const d = item.json;
    return {
        // ORDEM: Campanha, Grupo, Palavra-Chave, Termo
        "Campanha": d["Campanha"] || "N/A",
        "Grupo_Anuncio": d["Grupo de anúncios"] || "N/A",
        "Palavra_Chave": d["Palavra-chave"] || "N/A",
        "Termo": d["Termo de pesquisa"] || "N/A",

        // MÉTRICAS (Usando nomes exatos capturados na imagem Planilha Rush1)
        "Impressoes": String(d["Impr."] || "0"),
        "Cliques": String(d["Cliques"] || "0"),
        "CTR": String(d["CTR"] || "0%"),
        "Custo": String(d["Custo"] || "0"),
        "Conversoes": String(d["Conversões"] || "0"),
        "Custo_Conv": String(d["Custo / conv."] || "0")
    };
});

// 4. MONTA O INPUT FINAL PARA A IA
const inputParaIA = `
=== CONTEXTO DO SITE ===
${contextoSite.substring(0, 3000)}

=== DADOS PARA AUDITORIA ===
${JSON.stringify(listaEstruturada)}
`;

return {
    json: {
        meu_texto_pronto: inputParaIA
    }
};

