        const inicio = texto.indexOf('[');
        const fim = texto.lastIndexOf(']');

        if (inicio === -1 || fim === -1) {
            // Se não achou array, procura por objetos individuais {} (Plano B)
            const regexObj = /\{[\s\S]*?\}/g;
            const matches = texto.match(regexObj);
            if (matches) return matches.map(m => JSON.parse(m));
            throw new Error("A IA enviou apenas texto, sem formato de tabela.");
        }

        const apenasJSON = texto.substring(inicio, fim + 1);
        return JSON.parse(apenasJSON);
    } catch (e) {
        throw new Error("Falha ao processar a estrutura: " + e.message);
    }
}

try {
