// 1. CAPTURA O TEXTO DE FORMA MAIS ABRANGENTE
const item = $input.first();
let rawText = item.json.output || item.json.text || item.json.response || "";

// 2. LIMPEZA PROFUNDA (Remove Markdown, prefixos e quebras de linha estranhas)
rawText = rawText.replace(/```json/gi, "")
                 .replace(/```/gi, "")
                 .replace(/^json/gi, "")
                 .replace(/\\n/g, " ") // Remove quebras de linha escapadas
                 .trim();

// 3. FUNÇÃO DE EXTRAÇÃO COM SUPORTE A TEXTO ANTES/DEPOIS
function extrairJSON(texto) {
    try {
        const inicio = texto.indexOf('[');
        const fim = texto.lastIndexOf(']');

        if (inicio === -1 || fim === -1) {
            // Tenta achar apenas um objeto {} se não for lista
            const inicioObj = texto.indexOf('{');
            const fimObj = texto.lastIndexOf('}');
            if (inicioObj !== -1 && fimObj !== -1) {
                return [JSON.parse(texto.substring(inicioObj, fimObj + 1))];
            }
            throw new Error("A IA não retornou o formato de colchetes [ ].");
        }

        const apenasJSON = texto.substring(inicio, fim + 1);
        return JSON.parse(apenasJSON);
    } catch (e) {
        throw new Error("Erro de Sintaxe JSON: " + e.message);
    }
}

try {
    let dados = extrairJSON(rawText);
    if (!Array.isArray(dados)) dados = [dados];

    return dados.map(linha => {
        return {
            json: {
                "Campanha": linha["Campanha"] || "N/A",
                "Grupo de anúncios": linha["Grupo de anúncios"] || linha["Grupo_Anuncio"] || "N/A",
