                "NEGATIVAR": linha["NEGATIVAR"] || "",
                "TESTE_AB": linha["TESTE_AB"] || "",
                "DUVIDA": linha["DUVIDA"] || "",
                "Observacao": "Processado com sucesso",
                "Sugestao_Grupo": linha["Sugestao_Grupo"] || "",
