            "Palavra-chave": "Checar coluna Observacao",
            "debug_texto_ia": rawText.substring(0, 500)
        }
    }];
}

for (const item of $input.all()) {
  // Lê do maiúsculo (como vem da planilha) e salva no minúsculo (para o Supabase)
  item.json.segmentar = (item.json.SEGMENTAR === '✅' || item.json.SEGMENTAR === 'true' || item.json.SEGMENTAR === true);

  // Atenção aqui: o input é NEGATIVO, mas o Supabase espera negativar
  item.json.negativar = (item.json.NEGATIVO === '❌' || item.json.NEGATIVO === 'true' || item.json.NEGATIVO === true);

  item.json.teste_ab = (item.json.TESTE_AB === '⚠️' || item.json.TESTE_AB === 'true' || item.json.TESTE_AB === true);

  item.json.duvida = (item.json.DUVIDA === '❓' || item.json.DUVIDA === '?' || item.json.DUVIDA === 'true' || item.json.DUVIDA === true);

  // Limpeza: Apaga as chaves em maiúsculo para não enviar sujeira para o Supabase
  delete item.json.SEGMENTAR;
  delete item.json.NEGATIVO;
  delete item.json.TESTE_AB;
  delete item.json.DUVIDA;
}

return $input.all();

